  7	class BipartiteGraph {
  8	    private static final int UNCOLORED = -1;
  9	    private static final int FIRST_COLOR = 0;
 10	
 11	    static ArrayList<ArrayList<Integer>> constructadj(int vertexCount, int[][] edges) {
 12	        validateInput(vertexCount, edges);
 13	
 14	        ArrayList<ArrayList<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 15	
 16	        for (int[] edge : edges) {
 17	            addUndirectedEdge(adjacencyList, edge[0], edge[1]);
 18	        }
 19	
 20	        return adjacencyList;
 21	    }
 22	
 23	    static boolean isBipartite(int vertexCount, int[][] edges) {
 24	        ArrayList<ArrayList<Integer>> adjacencyList = constructadj(vertexCount, edges);
 25	
 26	        int[] colors = new int[vertexCount];
 27	        Arrays.fill(colors, UNCOLORED);
 28	
 29	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 30	            if (colors[vertex] == UNCOLORED && !colorComponent(vertex, adjacencyList, colors)) {
 31	                return false;
 32	            }
 33	        }
 34	
 35	        return true;
 36	    }
 37	
 38	    private static boolean colorComponent(
 39	            int startVertex,
 40	            List<? extends List<Integer>> adjacencyList,
 41	            int[] colors
 42	    ) {
 43	        Queue<Integer> queue = new ArrayDeque<>();
 44	        colors[startVertex] = FIRST_COLOR;
 45	        queue.offer(startVertex);
 46	
 47	        while (!queue.isEmpty()) {
 48	            int currentVertex = queue.poll();
 49	
 50	            for (int neighbor : adjacencyList.get(currentVertex)) {
 51	                if (colors[neighbor] == UNCOLORED) {
 52	                    colors[neighbor] = oppositeColor(colors[currentVertex]);
 53	                    queue.offer(neighbor);
 54	                } else if (colors[neighbor] == colors[currentVertex]) {
 55	                    return false;
 56	                }
 57	            }
 58	        }
 59	
 60	        return true;
 61	    }
 62	
 63	    private static int oppositeColor(int color) {
 64	        return 1 - color;
 65	    }
 66	
 67	    private static ArrayList<ArrayList<Integer>> createEmptyAdjacencyList(int vertexCount) {
 68	        ArrayList<ArrayList<Integer>> adjacencyList = new ArrayList<>();
 69	
 70	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 71	            adjacencyList.add(new ArrayList<>());
 72	        }
 73	
 74	        return adjacencyList;
 75	    }
 76	
 77	    private static void addUndirectedEdge(
 78	            ArrayList<ArrayList<Integer>> adjacencyList,
 79	            int sourceVertex,
 80	            int targetVertex
 81	    ) {
 82	        adjacencyList.get(sourceVertex).add(targetVertex);
 83	        adjacencyList.get(targetVertex).add(sourceVertex);
 84	    }
 85	
 86	    private static void validateInput(int vertexCount, int[][] edges) {
 87	        if (vertexCount < 0) {
 88	            throw new IllegalArgumentException("vertexCount must be non-negative");
 89	        }
 90	
 91	        if (edges == null) {
 92	            throw new IllegalArgumentException("edges must not be null");
 93	        }
 94	
 95	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
 96	            validateEdge(edges[edgeIndex], edgeIndex, vertexCount);
 97	        }
 98	    }
 99	
100	    private static void validateEdge(int[] edge, int edgeIndex, int vertexCount) {
101	        if (edge == null || edge.length < 2) {
102	            throw new IllegalArgumentException("edge at index " + edgeIndex + " must contain two vertices");
103	        }
104	
105	        validateVertex(edge[0], edgeIndex, vertexCount);
106	        validateVertex(edge[1], edgeIndex, vertexCount);
107	    }
108	
109	    private static void validateVertex(int vertex, int edgeIndex, int vertexCount) {
110	        if (vertex < 0 || vertex >= vertexCount) {
111	            throw new IllegalArgumentException(
112	                    "edge at index " + edgeIndex + " references invalid vertex " + vertex
113	            );
114	        }
115	    }
116	
117	    public static void main(String[] args) {
118	        int vertexCount = 4;
119	
120	        int[][] edges = {{0, 1}, {0, 2}, {1, 2}, {2, 3}};
121	
122	        System.out.println(isBipartite(vertexCount, edges));
123	    }
124	}

